// Actions-only strict authenticated recipient user-read DTO/no-store/privacy.
#[tokio::test]
async fn recipient_user_read_http_requires_auth_and_refuses_caller_uid_index_route_or_reply_grants(){
 let state=build_test_router().await.expect("Actions private bus required; no skip");let served=serve(state.router.clone()).await;let path="/api/non-3gpp/accounts/app-account-0123456789abcdef0123456789abcdef/im-messages/1/mark-read/recipient";let(status,_,body)=account_request(&served,reqwest::Method::POST,path,None,None).await;assert_eq!(status,StatusCode::UNAUTHORIZED);no_secrets(&body);let cookie=authenticate(&served).await;
 for key in ["uid","token","index","url","scope","reply","resolved_uid"]{let mut data=serde_json::json!({"expected_revision":1,"nonce":"a".repeat(32),"recipient":"[phone:+12345@fixture.invalid]","consent":true});data[key]=serde_json::json!("fixture-private-no-echo");let(status,headers,body)=account_request(&served,reqwest::Method::POST,path,Some(data),Some(&cookie)).await;assert_eq!(status,StatusCode::BAD_REQUEST);no_store(&headers);no_secrets(&body);assert!(!body.contains("12345"));}assert!(state.app.app_accounts.list(100).await.unwrap().is_empty());
}
#[tokio::test]
async fn recipient_user_read_http_needs_explicit_consent_current_revision_and_running_original_policy(){
 let state=build_test_router().await.expect("Actions private bus required; no skip");let served=serve(state.router.clone()).await;let cookie=authenticate(&served).await;let cert=Certificates::generate("IP:127.0.0.1");let(status,_,body)=account_request(&served,reqwest::Method::POST,"/api/non-3gpp/accounts",Some(serde_json::json!({"provider_id":"app_voice","config":im_runtime_config_json(&cert.root)})),Some(&cookie)).await;assert_eq!(status,StatusCode::CREATED);let line=created_line(&body);let path=format!("/api/non-3gpp/accounts/{line}/im-messages/1/mark-read/recipient");
 for(revision,consent,want)in[(1,false,StatusCode::FORBIDDEN),(2,true,StatusCode::CONFLICT),(1,true,StatusCode::SERVICE_UNAVAILABLE)]{let(status,headers,body)=account_request(&served,reqwest::Method::POST,&path,Some(serde_json::json!({"expected_revision":revision,"nonce":"a".repeat(32),"recipient":"[phone:+12345@fixture.invalid]","consent":consent})),Some(&cookie)).await;assert_eq!(status,want);no_store(&headers);no_secrets(&body);assert!(!body.contains("12345"));}let view=state.app.app_accounts.get(&line,100).await.unwrap();assert_eq!(view.phase,"stopped");assert!(view.im_user_read_recipient_supported.is_none());assert!(!view.incoming_message_ready&&!view.incoming_call_ready&&!view.outbound_authorized);
}
#[tokio::test]
async fn recipient_user_read_http_naked_alias_uid_or_ambiguous_id_nonce_cannot_create_user_intent(){
 let state=build_test_router().await.expect("Actions private bus required; no skip");let served=serve(state.router.clone()).await;let cookie=authenticate(&served).await;let base="/api/non-3gpp/accounts/app-account-0123456789abcdef0123456789abcdef/im-messages";
 for id in ["0","01","-1","9223372036854775808"]{let(status,headers,body)=account_request(&served,reqwest::Method::POST,&format!("{base}/{id}/mark-read/recipient"),Some(serde_json::json!({"expected_revision":1,"nonce":"a".repeat(32),"recipient":"[phone:+12345@fixture.invalid]","consent":true})),Some(&cookie)).await;assert_eq!(status,StatusCode::BAD_REQUEST);no_store(&headers);no_secrets(&body);}
 for uri in ["7_9","[uid:7_9]","12345","scheme://fixture.invalid"]{let(status,headers,body)=account_request(&served,reqwest::Method::POST,&format!("{base}/1/mark-read/recipient"),Some(serde_json::json!({"expected_revision":1,"nonce":"a".repeat(32),"recipient":uri,"consent":true})),Some(&cookie)).await;assert_eq!(status,StatusCode::BAD_REQUEST);no_store(&headers);no_secrets(&body);}assert!(state.app.app_accounts.list(100).await.unwrap().is_empty());
}
